<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>桐生12R 予想分析</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400;500;700;900&amp;display=swap');

:root {
--bg: #0b1220;
--card: #141e2e;
--accent: #00c2ff;
--gold: #f0c040;
--red: #ff4d6d;
--green: #2dd4a8;
--text: #e8eef7;
--muted: #8b9bb4;
--border: rgba(255,255,255,0.08);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
font-family: 'Noto Sans JP', sans-serif;
background: var(--bg);
color: var(--text);
line-height: 1.7;
min-height: 100vh;
padding: 28px 16px 60px;
background-image:
radial-gradient(ellipse at 20% 0%, rgba(0,194,255,0.12), transparent 50%),
radial-gradient(ellipse at 80% 100%, rgba(240,192,64,0.08), transparent 45%);
}

.container { max-width: 720px; margin: 0 auto; }

header {
text-align: center;
margin-bottom: 28px;
padding: 22px 16px;
border-radius: 16px;
background: linear-gradient(135deg, rgba(20,30,46,0.95), rgba(15,25,40,0.9));
border: 1px solid var(--border);
box-shadow: 0 8px 32px rgba(0,0,0,0.35);
}

header .badge {
display: inline-block;
font-size: 11px;
letter-spacing: 0.12em;
color: var(--accent);
border: 1px solid rgba(0,194,255,0.4);
padding: 3px 10px;
border-radius: 999px;
margin-bottom: 10px;
font-weight: 700;
}

h1 {
font-size: 1.55rem;
font-weight: 900;
letter-spacing: 0.04em;
background: linear-gradient(90deg, #fff, var(--gold));
-webkit-background-clip: text;
-webkit-text-fill-color: transparent;
background-clip: text;
}

.sub {
color: var(--muted);
font-size: 0.85rem;
margin-top: 6px;
}

.section {
background: var(--card);
border: 1px solid var(--border);
border-radius: 14px;
padding: 20px 18px 18px;
margin-bottom: 18px;
box-shadow: 0 4px 20px rgba(0,0,0,0.25);
}

.section-title {
display: flex;
align-items: center;
gap: 10px;
font-size: 1.05rem;
font-weight: 700;
margin-bottom: 14px;
padding-bottom: 10px;
border-bottom: 1px solid var(--border);
}

.section-title .icon {
width: 28px;
height: 28px;
border-radius: 8px;
display: grid;
place-items: center;
font-size: 14px;
background: rgba(0,194,255,0.15);
color: var(--accent);
}

.section.conclusion .section-title .icon { background: rgba(240,192,64,0.15); color: var(--gold); }
.section.kaime .section-title .icon { background: rgba(45,212,168,0.15); color: var(--green); }

p { color: #c5d0e0; font-size: 0.92rem; margin-bottom: 10px; }
p:last-child { margin-bottom: 0; }

